import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    idx = 1

    ans = 0
    speed = 0
    limit = 10**9
    overtake_allowed = True

    # stack of active speed limits, with their event index
    limits = []
    # stack of active "no overtake" signs, with their event index
    no_overtake = []

    for i in range(n):
        t = int(data[idx]); idx += 1
        if t == 1:
            speed = int(data[idx]); idx += 1
        elif t == 2:
            if not overtake_allowed:
                ans += len(no_overtake)
                no_overtake.clear()
                overtake_allowed = True
        elif t == 3:
            s = int(data[idx]); idx += 1
            limits.append((s, i))
            limit = s
        elif t == 4:
            overtake_allowed = True
            no_overtake.clear()
        elif t == 5:
            limits.clear()
            limit = 10**9
        elif t == 6:
            if overtake_allowed:
                overtake_allowed = False
            no_overtake.append(i)

        # remove speed limits that are no longer relevant
        while limits and limits[-1][0] < speed:
            limits.pop()
        if limits:
            limit = limits[-1][0]
        else:
            limit = 10**9

        # if current speed exceeds the active limit, we must ignore that limit sign
        if speed > limit:
            # find the most recent limit that is below speed
            # all limits below speed must be ignored
            while limits and limits[-1][0] < speed:
                ans += 1
                limits.pop()
            if limits:
                limit = limits[-1][0]
            else:
                limit = 10**9

    print(ans)

if __name__ == "__main__":
    main()
